    internal static int WriteIntegerNullableOrDecimalNullableTotal(
        GraphBuilder graph,
        IntegerNullableOrDecimalNullableTotal value
    )
    {
        return value.Value switch
        {
            AddIntegerNullableTotal item => WriteAddIntegerNullableTotal(graph, item),
            SubtractIntegerNullableTotal item => WriteSubtractIntegerNullableTotal(graph, item),
            MultiplyIntegerNullableTotal item => WriteMultiplyIntegerNullableTotal(graph, item),
            IntegerDivideIntegerNullableTotal item => WriteIntegerDivideIntegerNullableTotal(graph, item),
            ModuloIntegerNullableTotal item => WriteModuloIntegerNullableTotal(graph, item),
            FloorIntegerNullableTotal item => WriteFloorIntegerNullableTotal(graph, item),
            CeilingIntegerNullableTotal item => WriteCeilingIntegerNullableTotal(graph, item),
            RoundWithDigitsIntegerNullableTotal item => WriteRoundWithDigitsIntegerNullableTotal(graph, item),
            RoundWithoutDigitsIntegerNullableTotal item => WriteRoundWithoutDigitsIntegerNullableTotal(graph, item),
            TruncateWithDigitsIntegerNullableTotal item => WriteTruncateWithDigitsIntegerNullableTotal(graph, item),
            TruncateWithoutDigitsIntegerNullableTotal item => WriteTruncateWithoutDigitsIntegerNullableTotal(graph, item),
            AbsIntegerNullableTotal item => WriteAbsIntegerNullableTotal(graph, item),
            SignIntegerNullableTotal item => WriteSignIntegerNullableTotal(graph, item),
            LengthIntegerNullableTotal item => WriteLengthIntegerNullableTotal(graph, item),
            PositionIntegerNullableTotal item => WritePositionIntegerNullableTotal(graph, item),
            DateDiffDaysIntegerNullableTotal item => WriteDateDiffDaysIntegerNullableTotal(graph, item),
            DateDiffMonthsIntegerNullableTotal item => WriteDateDiffMonthsIntegerNullableTotal(graph, item),
            DatetimeDiffMonthsIntegerNullableTotal item => WriteDatetimeDiffMonthsIntegerNullableTotal(graph, item),
            YearDateIntegerNullableTotal item => WriteYearDateIntegerNullableTotal(graph, item),
            YearDatetimeIntegerNullableTotal item => WriteYearDatetimeIntegerNullableTotal(graph, item),
            QuarterDateIntegerNullableTotal item => WriteQuarterDateIntegerNullableTotal(graph, item),
            QuarterDatetimeIntegerNullableTotal item => WriteQuarterDatetimeIntegerNullableTotal(graph, item),
            MonthDateIntegerNullableTotal item => WriteMonthDateIntegerNullableTotal(graph, item),
